#include <libretiny.h>
#include <sdk_private.h>

extern void rtos_set_user_app_entry(beken_thread_function_t entry);
extern int bk_init(void);
extern int lt_main(void);

// Build identifier, normally generated by the ARMINO build system
volatile const char build_version[] = __DATE__ " " __TIME__;

// crti.o/crtn.o are not linked (-nostartfiles); called by __libc_init_array()
void _init(void) {}

void _fini(void) {}

// normally provided by crtbegin.o, used by __cxa_atexit() for C++ static objects
void *__dso_handle = &__dso_handle;

static void lt_armino_entry(void *arg) {
	lt_main();
}

// Called by the ARMINO app main thread (components/bk_startup/system_main.c
// is compiled with main=lt_armino_main)
int lt_armino_main(void) {
	rtos_set_user_app_entry(lt_armino_entry);
	bk_init();
	return 0;
}
